func (s *Store) Edit(ctx context.Context, id int64, fn func(*Cluster) error) error {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback()
	if _, err = tx.ExecContext(ctx, "SELECT pg_advisory_xact_lock($1)", id); err != nil { // root lock
		return err
	}
	c, err := loadCluster(ctx, tx, id) // members need no own locks
	if err == nil {
		err = fn(c)
	}
	if err != nil {
		return err
	}
	return tx.Commit()
}
